entence": "민수는 물 [ ? ] 마셔요.", "options": ["을", "를"], "answer": "을", "feedback": {"correct": "Great! 물 ends in a consonant, so + 을"}}, {"type": "fill_blank", "instruction": "Yumi likes coffee.", "sentence": "유미는 커피 [ ? ] 좋아해요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Perfect! 커피 ends in a vowel, so + 를"}}]}}, {"step_type": "intro", "title": "Vocabulary: Food & Things", "instruction": "Words you can use with 을/를.", "content": {"explanation": {"title": "Useful words"}, "sentences": [{"korean": "커피", "english": "Coffee", "tts": true, "chunks": [{"display": "커피", "tokens": [{"text": "커피", "meaning": "coffee"}]}]}, {"korean": "빵", "english": "Bread", "tts": true, "chunks": [{"display": "빵", "tokens": [{"text": "빵", "meaning": "bread"}]}]}, {"korean": "물", "english": "Water", "tts": true, "chunks": [{"display": "물", "tokens": [{"text": "물", "meaning": "water"}]}]}, {"korean": "사과", "english": "Apple", "tts": true, "chunks": [{"display": "사과", "tokens": [{"text": "사과", "meaning": "apple"}]}]}, {"korean": "책", "english": "Book", "tts": true, "chunks": [{"display": "책", "tokens": [{"text": "책", "meaning": "book"}]}]}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"I like coffee.\"", "contentObj": {"sentence": "저는 커피를 좋아해요.", "translation": "I like coffee.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["커피를"], "correct_turtle": ["커피", "를"], "turtle_explanation": "'를' marks the object. After a vowel use 를, after a consonant use 을."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["좋아해요"], "correct_turtle": ["좋아해요"], "turtle_explanation": "Keep '좋아해요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "저는", "mode": "turtle"}, {"id": "o2", "text": "좋아해요", "mode": "turtle"}, {"id": 